def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected 1 match, found {count}')
    return text.replace(old, new, 1)


queue_constants = """const LEADERBOARD_SUBMISSION_QUEUE_KEY='voidcut.leaderboard.submissions.v1';
const LEADERBOARD_SUBMISSION_QUEUE_LIMIT=16;
const LEADERBOARD_QUEUE_RETRY_MS=15000;
"""

queue_block = r"""function normalizeLeaderboardSubmissionQueue(raw,now=Date.now()){if(!Array.isArray(raw))return[];const out=[],seen=new Set;for(const item of raw){const ticket=item?.ticket,replay=item?.replay,id=String(item?.id||ticket?.ticketId||''),expiresAt=Number(ticket?.expiresAt)||0;if(!id||seen.has(id)||!ticket||String(ticket.ticketId||'')!==id||!replay||typeof replay!=='object'||!Number.isFinite(expiresAt)||expiresAt<=now+1000)continue;seen.add(id);out.push({id,ticket,replay,queuedAt:Number(item?.queuedAt)||now})}return out.slice(-LEADERBOARD_SUBMISSION_QUEUE_LIMIT)}
function loadLeaderboardSubmissionQueue(){try{return normalizeLeaderboardSubmissionQueue(JSON.parse(localStorage.getItem(LEADERBOARD_SUBMISSION_QUEUE_KEY)||'[]'))}catch{try{localStorage.removeItem(LEADERBOARD_SUBMISSION_QUEUE_KEY)}catch{}return[]}}
function persistLeaderboardSubmissionQueue(queue=leaderboardSubmissionQueue){const clean=normalizeLeaderboardSubmissionQueue(queue);leaderboardSubmissionQueue=clean;try{const text=JSON.stringify(clean);localStorage.setItem(LEADERBOARD_SUBMISSION_QUEUE_KEY,text);return localStorage.getItem(LEADERBOARD_SUBMISSION_QUEUE_KEY)===text}catch{return false}}
function enqueueLeaderboardSubmission(replay,ticket){const id=String(ticket?.ticketId||''),expiresAt=Number(ticket?.expiresAt)||0;if(!id||!replay||typeof replay!=='object'||!Number.isFinite(expiresAt)||expiresAt<=Date.now()+1000)return'invalid';const base=normalizeLeaderboardSubmissionQueue(leaderboardSubmissionQueue).filter(x=>x.id!==id);if(base.length>=LEADERBOARD_SUBMISSION_QUEUE_LIMIT)return'full';return persistLeaderboardSubmissionQueue([...base,{id,ticket,replay,queuedAt:Date.now()}])?'queued':'volatile'}
function removeLeaderboardSubmission(id){leaderboardSubmissionQueue=leaderboardSubmissionQueue.filter(x=>x.id!==id);const ok=persistLeaderboardSubmissionQueue(leaderboardSubmissionQueue);if(!leaderboardSubmissionQueue.length&&leaderboardQueueRetryTimer!==null){clearTimeout(leaderboardQueueRetryTimer);leaderboardQueueRetryTimer=null}return ok}
function terminalLeaderboardSubmissionError(err){return[400,403,404,409,410,413,422].includes(Number(err?.status)||0)}
function scheduleLeaderboardQueueRetry(){if(leaderboardQueueRetryTimer!==null||!leaderboardSubmissionQueue.length||!loadLeaderboardIdentity()||navigator.onLine===false)return;leaderboardQueueRetryTimer=setTimeout(()=>{leaderboardQueueRetryTimer=null;void drainLeaderboardSubmissionQueue()},LEADERBOARD_QUEUE_RETRY_MS)}
async function submitLeaderboardQueueEntry(entry){return leaderboardRequest(`/run/submit/${encodeURIComponent(entry.ticket.ticketId)}`,{method:'POST',body:JSON.stringify(entry.replay)},true)}
async function drainLeaderboardSubmissionQueue(){if(leaderboardQueueDrainPromise)return leaderboardQueueDrainPromise;leaderboardSubmissionQueue=normalizeLeaderboardSubmissionQueue(leaderboardSubmissionQueue);persistLeaderboardSubmissionQueue(leaderboardSubmissionQueue);if(!leaderboardSubmissionQueue.length)return null;if(!loadLeaderboardIdentity()){showLeaderboardJoin(`${leaderboardSubmissionQueue.length} ranked run${leaderboardSubmissionQueue.length===1?' is':'s are'} safely queued. Choose a public name to submit ${leaderboardSubmissionQueue.length===1?'it':'them'}.`);return null}leaderboardQueueDrainPromise=(async()=>{while(leaderboardSubmissionQueue.length){const entry=leaderboardSubmissionQueue[0];if(Number(entry.ticket?.expiresAt)<=Date.now()+1000){removeLeaderboardSubmission(entry.id);appendLeaderboardResult('GLOBAL QUEUED RUN EXPIRED');continue}try{appendLeaderboardResult('GLOBAL VERIFYING');const data=await submitLeaderboardQueueEntry(entry);removeLeaderboardSubmission(entry.id);ui.newBest.textContent=(ui.newBest.textContent||'').replace(/(?: • )?GLOBAL VERIFYING/g,'');hideLeaderboardJoin();const rank=data?.rank?`GLOBAL #${Number(data.rank).toLocaleString()}`:'GLOBAL VERIFIED';appendLeaderboardResult(data?.personalBest?`${rank} • PERSONAL BEST`:rank)}catch(err){ui.newBest.textContent=(ui.newBest.textContent||'').replace(/(?: • )?GLOBAL VERIFYING/g,'');if(err?.status===401){clearLeaderboardIdentity();showLeaderboardJoin(`${leaderboardSubmissionQueue.length} queued ranked run${leaderboardSubmissionQueue.length===1?' needs':'s need'} a valid leaderboard identity before submission.`);break}if(terminalLeaderboardSubmissionError(err)){removeLeaderboardSubmission(entry.id);appendLeaderboardResult('GLOBAL QUEUED RUN REJECTED');continue}appendLeaderboardResult('GLOBAL SUBMISSION QUEUED');scheduleLeaderboardQueueRetry();break}}if(!leaderboardSubmissionQueue.length)hideLeaderboardJoin()})().finally(()=>{leaderboardQueueDrainPromise=null});return leaderboardQueueDrainPromise}
function queueLeaderboardSubmission(replay,ticket){if(!replay||!ticket)return false;const result=enqueueLeaderboardSubmission(replay,ticket);if(result==='invalid')return false;if(result==='full'){appendLeaderboardResult('GLOBAL QUEUE FULL');return false}if(result==='volatile')appendLeaderboardResult('GLOBAL QUEUE STORAGE FAILED');if(loadLeaderboardIdentity())void drainLeaderboardSubmissionQueue();else showLeaderboardJoin(`${leaderboardSubmissionQueue.length} ranked run${leaderboardSubmissionQueue.length===1?' is':'s are'} queued. Choose one public name to submit ${leaderboardSubmissionQueue.length===1?'it':'them'}.`);return result==='queued'}
leaderboardSubmissionQueue=loadLeaderboardSubmissionQueue();
window.addEventListener('online',()=>void drainLeaderboardSubmissionQueue());
"""

old_profile = "async function createLeaderboardProfileFromCard(){const input=$('leaderboardNameInput'),button=$('leaderboardJoinButton'),status=$('leaderboardJoinStatus'),name=(input?.value||'').trim().replace(/\\s+/g,' ');if(!/^[A-Za-z0-9 _-]{3,16}$/.test(name)){status.textContent='Use 3–16 letters, numbers, spaces, _ or -.';return}button.disabled=true;status.textContent='CREATING PROFILE…';try{const data=await leaderboardRequest('/profile/create',{method:'POST',body:JSON.stringify({name})},false);if(!data?.player?.id||!data?.token)throw new Error('Invalid profile response');storeLeaderboardIdentity({playerId:data.player.id,name:data.player.name,token:data.token});status.textContent='PROFILE READY • VERIFYING RUN…';if(pendingLeaderboardSubmission)await submitLeaderboardRun(pendingLeaderboardSubmission.replay,pendingLeaderboardSubmission.ticket)}catch(err){status.textContent=err?.code==='name-taken'?'NAME ALREADY TAKEN':String(err?.message||'PROFILE CREATION FAILED').toUpperCase()}finally{button.disabled=false}}"
new_profile = "async function createLeaderboardProfileFromCard(){const input=$('leaderboardNameInput'),button=$('leaderboardJoinButton'),status=$('leaderboardJoinStatus'),name=(input?.value||'').trim().replace(/\\s+/g,' ');if(!/^[A-Za-z0-9 _-]{3,16}$/.test(name)){status.textContent='Use 3–16 letters, numbers, spaces, _ or -.';return}button.disabled=true;status.textContent='CREATING PROFILE…';try{const data=await leaderboardRequest('/profile/create',{method:'POST',body:JSON.stringify({name})},false);if(!data?.player?.id||!data?.token)throw new Error('Invalid profile response');storeLeaderboardIdentity({playerId:data.player.id,name:data.player.name,token:data.token});status.textContent=leaderboardSubmissionQueue.length?`PROFILE READY • VERIFYING ${leaderboardSubmissionQueue.length} QUEUED RUN${leaderboardSubmissionQueue.length===1?'':'S'}…`:'PROFILE READY';await drainLeaderboardSubmissionQueue()}catch(err){status.textContent=err?.code==='name-taken'?'NAME ALREADY TAKEN':String(err?.message||'PROFILE CREATION FAILED').toUpperCase()}finally{button.disabled=false}}"
old_submit = "async function submitLeaderboardRun(replay,ticket){if(!replay||!ticket)return;const ident=loadLeaderboardIdentity();if(!ident){pendingLeaderboardSubmission={replay,ticket};showLeaderboardJoin();return}try{appendLeaderboardResult('GLOBAL VERIFYING');const data=await leaderboardRequest(`/run/submit/${encodeURIComponent(ticket.ticketId)}`,{method:'POST',body:JSON.stringify(replay)},true);pendingLeaderboardSubmission=null;hideLeaderboardJoin();const rank=data?.rank?`GLOBAL #${Number(data.rank).toLocaleString()}`:'GLOBAL VERIFIED';ui.newBest.textContent=(ui.newBest.textContent||'').replace(/(?: • )?GLOBAL VERIFYING/g,'');appendLeaderboardResult(data?.personalBest?`${rank} • PERSONAL BEST`:rank)}catch(err){ui.newBest.textContent=(ui.newBest.textContent||'').replace(/(?: • )?GLOBAL VERIFYING/g,'');if(err?.status===401){clearLeaderboardIdentity();pendingLeaderboardSubmission={replay,ticket};showLeaderboardJoin('Your local leaderboard identity expired. Choose a name to create a new one and submit this run.')}else appendLeaderboardResult('GLOBAL SUBMISSION FAILED')}}\nfunction queueLeaderboardSubmission(replay,ticket){if(!replay||!ticket)return;pendingLeaderboardSubmission={replay,ticket};if(loadLeaderboardIdentity())void submitLeaderboardRun(replay,ticket);else showLeaderboardJoin()}\n"

