anchor = "async function acquireLeaderboardTicket(waitMs=RANKED_START_WAIT_MS){const ready=takeLeaderboardTicket();if(ready)return{ticket:ready,reason:null};const request=prefetchLeaderboardTicket();let timer=null;const outcome=await Promise.race([request.then(()=>'settled'),new Promise(resolve=>{timer=setTimeout(()=>resolve('timeout'),Math.max(0,Number(waitMs)||0))})]);if(timer!==null)clearTimeout(timer);const ticket=takeLeaderboardTicket();if(ticket)return{ticket,reason:null};return{ticket:null,reason:outcome==='timeout'?'LEADERBOARD TIMEOUT':'LEADERBOARD UNAVAILABLE'}}\n"
c = replace_once(c, anchor, anchor + queue_block, 'client queue block')
